-- Тема 2: Обязанности водителей — топик id=2, категория id=1
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(1,2,'Какие документы обязан иметь при себе водитель механического ТС?',
'["Только водительское удостоверение","Водительское удостоверение, регистрационные документы на ТС и страховой полис ОСАГО","Только страховой полис","Документы не требуются, если ТС технически исправно"]'::jsonb,1,
'Водитель обязан иметь при себе и по требованию сотрудников полиции передавать им для проверки водительское удостоверение, регистрационные документы на ТС и страховой полис ОСАГО.',1),
(1,2,'В каком случае водитель обязан уступить дорогу транспортному средству с включённым проблесковым маячком синего цвета и специальным звуковым сигналом?',
'["Только если это ТС скорой помощи","Независимо от цвета маячка и типа ТС при включении спецсигнала","Только на перекрёстках","Только вне населённых пунктов"]'::jsonb,1,
'Водитель обязан уступить дорогу ТС, имеющим нанесённые на наружные поверхности специальные цветографические схемы, надписи и обозначения, с включёнными проблесковым маячком синего цвета и специальным звуковым сигналом независимо от направления его дальнейшего движения.',2),
(1,2,'Обязан ли водитель проходить медицинское освидетельствование по требованию сотрудника полиции?',
'["Нет, это право водителя, а не обязанность","Да, водитель обязан проходить освидетельствование на состояние опьянения по требованию сотрудников полиции","Только если у него есть подозрительные симптомы","Только по решению суда"]'::jsonb,1,
'Водитель обязан проходить по требованию сотрудников полиции освидетельствование на состояние алкогольного опьянения и медицинское освидетельствование на состояние опьянения.',3),
(1,2,'Что обязан сделать водитель перед выездом на линию?',
'["Проверить и обеспечить в пути следования исправное техническое состояние ТС","Только заправить топливом","Ничего, кроме проверки документов","Помыть автомобиль"]'::jsonb,0,
'Водитель обязан перед выездом проверить и в пути следования обеспечивать исправное техническое состояние транспортного средства в соответствии с Основными положениями по допуску ТС к эксплуатации.',4),
(1,2,'Разрешена ли водителю передача управления транспортным средством лицу, находящемуся в состоянии опьянения?',
'["Да, если это лицо имеет водительское удостоверение","Нет, запрещена","Да, на короткое расстояние","Да, если поблизости нет сотрудников полиции"]'::jsonb,1,
'Водителю запрещается передавать управление транспортным средством лицу, находящемуся в состоянии опьянения, под воздействием лекарственных препаратов или в болезненном состоянии.',5),
(1,2,'Что должен предпринять водитель, причастный к ДТП, в первую очередь?',
'["Уехать с места происшествия для вызова помощи","Немедленно остановить (не трогать) транспортное средство, включить аварийную сигнализацию и выставить знак аварийной остановки","Убрать ТС с проезжей части до приезда ГИБДД в любом случае","Дождаться очевидцев"]'::jsonb,1,
'При ДТП водитель обязан немедленно остановить (не трогать с места) ТС, включить аварийную сигнализацию и выставить знак аварийной остановки, не перемещать предметы, имеющие отношение к происшествию.',6),
(1,2,'Обязан ли водитель по требованию пассажиров с детьми предоставлять детские удерживающие устройства?',
'["Нет такой обязанности","Водитель обязан перевозить детей с использованием детских удерживающих устройств, соответствующих весу и росту ребёнка","Только детей старше 7 лет","Только в такси"]'::jsonb,1,
'Перевозка детей в возрасте младше 7 лет в легковом автомобиле должна осуществляться с использованием детских удерживающих устройств, соответствующих весу и росту ребёнка.',7),
(1,2,'Что обязан сделать водитель при приближении транспортного средства с включёнными проблесковыми маячками жёлтого или оранжевого цвета?',
'["Уступить дорогу в обязательном порядке при выполнении им работ на дороге","Никак не реагировать","Обязательно остановиться","Ускориться, чтобы быстрее проехать"]'::jsonb,0,
'Водитель ТС с включённым проблесковым маячком жёлтого или оранжевого цвета при выполнении работ по строительству, ремонту или содержанию дорог вправе отступать от требований разметки, знаков — другие водители должны соблюдать особую осторожность.',8),
(1,2,'Может ли водитель пользоваться телефоном без гарнитуры во время движения?',
'["Да, если это необходимо","Нет, запрещено пользоваться телефоном, не оборудованным техническим устройством для передачи речи без использования рук","Да, только на короткие звонки","Да, если ТС стоит на светофоре"]'::jsonb,1,
'Водителю запрещается пользоваться во время движения телефоном, не оборудованным техническим устройством, позволяющим вести переговоры без использования рук.',9),
(1,2,'В каком случае водитель обязан включить внешние световые приборы в светлое время суток?',
'["Только в туман","При движении вне населённых пунктов на мотоциклах и в организованной колонне, а также по требованию правил в определённых регионах","Никогда не требуется","Только на автомагистралях"]'::jsonb,1,
'Ближний свет фар или дневные ходовые огни должны быть включены на движущемся ТС в светлое время суток, а также обязательно на мотоциклах и в организованных транспортных колоннах.',10),
(1,2,'Обязан ли водитель уступать дорогу слепым пешеходам, подающим сигнал белой тростью?',
'["Нет, слепой пешеход должен сам обеспечить безопасность","Да, водитель обязан снизить скорость или остановиться и уступить дорогу","Только на пешеходных переходах","Только в тёмное время суток"]'::jsonb,1,
'Водитель обязан снизить скорость вплоть до остановки, чтобы пропустить пешехода, подающего сигнал белой тростью, независимо от места перехода.',11);
